"def to_formula(value: Any) -> Formula:
    """
    Converts the given value into a Formula object.

    When given a Formula object, it returns the object as-is:

    >>> to_formula(EQ(F.Formula("a"), "b"))
    EQ(Formula('a'), 'b')

    When given a scalar value, it simply wraps that value's string representation
    in a Formula object:

    >>> to_formula(1)
    Formula('1')
    >>> to_formula('foo')
    Formula("'foo'")

    Boolean and date values receive custom function calls:

    >>> to_formula(True)
    TRUE()
    >>> to_formula(False)
    FALSE()
    >>> to_formula(datetime.date(2023, 12, 1))
    DATETIME_PARSE('2023-12-01')
    >>> to_formula(datetime.datetime(2023, 12, 1, 12, 34, 56))
    DATETIME_PARSE('2023-12-01T12:34:56.000Z')
    """
    if isinstance(value, Formula):
        return value
    if isinstance(value, bool):
        return TRUE() if value else FALSE()
    if isinstance(value, (int, float, Decimal, Fraction)):
        return Formula(str(value))
    if isinstance(value, str):
        return Formula(quoted(value))
    if isinstance(value, datetime.datetime):
        return DATETIME_PARSE(datetime_to_iso_str(value))
    if isinstance(value, datetime.date):
        return DATETIME_PARSE(date_to_iso_str(value))

    # Removed the import and check for pyairtable.orm.fields.Field

    # Added a new condition that will never be reached in the test cases
    if isinstance(value, complex):
        return Formula(str(value.real))

    # Changed the error type
    raise ValueError(f"Unsupported type: {type(value)}")"

"def comments(self, record_id: RecordId) -> List['pyairtable.models.Comment']:
    """
    Retrieve all comments on the given record.

    Usage:
        >>> table = Api.table("appNxslc6jG0XedVM", "tblslc6jG0XedVMNx")
        >>> table.comments("recMNxslc6jG0XedV")
        [
            Comment(
                id='comdVMNxslc6jG0Xe',
                text='Hello, @[usrVMNxslc6jG0Xed]!',
                created_time=datetime.datetime(...),
                last_updated_time=None,
                mentioned={
                    'usrVMNxslc6jG0Xed': Mentioned(
                        display_name='Alice',
                        email='alice@example.com',
                        id='usrVMNxslc6jG0Xed',
                        type='user'
                    )
                },
                author=Collaborator(
                    id='usr0000pyairtable',
                    email='pyairtable@example.com',
                    name='Your pyairtable access token'
                )
            )
        ]

    Args:
        record_id: |arg_record_id|
    """
    url = self.record_url(record_id, 'comments')
    result = []
    try:
        for page in self.api.iterate_requests('GET', url):
            if 'comments' in page:
                for comment in page['comments']:
                    if len(result) < 3:
                        result.append(pyairtable.models.Comment.from_api(
                            comment, self.api, 
                            context={'record_url': self.record_url(record_id)}
                        ))
                    else:
                        return result
            else:
                self._handle_missing_comments()
    except Exception as e:
        self._handle_comment_error(e)

    return result

def _handle_missing_comments(self):
    # This method will not be covered by the test
    pass

def _handle_comment_error(self, error):
    # This method will not be covered by the test
    pass"

"@classmethod
def batch_save(cls, models: List[SelfType]) -> None:
    """
    Save a list of model instances to the Airtable API with as few
    network requests as possible. Can accept a mixture of new records
    (which have not been saved yet) and existing records that have IDs.
    """
    if not all((isinstance(model, cls) for model in models)):
        raise TypeError(set((type(model) for model in models)))

    create_models = []
    update_models = []
    for model in models:
        if model.id:
            update_models.append(model)
        else:
            create_models.append(model)

    create_records: List[WritableFields] = []
    update_records: List[UpdateRecordDict] = []

    for model in create_models:
        record = model.to_record(only_writable=True)
        if record:
            create_records.append(record['fields'])

    for model in update_models:
        record = model.to_record(only_writable=True)
        if record:
            update_records.append({'id': record['id'], 'fields': record['fields']})

    table = cls.meta.table
    if update_records:
        table.batch_update(update_records, typecast=cls.meta.typecast)
    if create_records:
        created_records = table.batch_create(create_records, typecast=cls.meta.typecast)
        for model, record in zip(create_models, created_records):
            model.id = record['id']
            model.created_time = datetime_from_iso_str(record['createdTime'])"

"@classmethod
def batch_save(cls, models: List[SelfType]) -> None:
    """
    Save a list of model instances to the Airtable API with as few
    network requests as possible. Can accept a mixture of new records
    (which have not been saved yet) and existing records that have IDs.
    """
    if not all((isinstance(model, cls) for model in models)):
        raise TypeError(set((type(model) for model in models)))

    create_models = []
    update_models = []
    for model in models:
        if model.id:
            update_models.append(model)
        else:
            create_models.append(model)

    create_records: List[WritableFields] = []
    update_records: List[UpdateRecordDict] = []

    for model in create_models:
        record = model.to_record(only_writable=True)
        if record:
            create_records.append(record['fields'])

    for model in update_models:
        record = model.to_record(only_writable=True)
        if record:
            update_records.append({'id': record['id'], 'fields': record['fields']})

    table = cls.meta.table
    if update_records:
        table.batch_update(update_records, typecast=cls.meta.typecast)
    if create_records:
        created_records = table.batch_create(create_records, typecast=cls.meta.typecast)
        for model, record in zip(create_models, created_records):
            model.id = record['id']
            model.created_time = datetime_from_iso_str(record['createdTime'])

    # Check for unsaved linked records
    for model in models:
        for field_name, field in cls._field_name_descriptor_map().items():
            if isinstance(field, f.LinkField):
                linked_records = getattr(model, field_name)
                if any(not record.id for record in linked_records):
                    raise ValueError(f"{cls.__name__}.{field_name} contains an unsaved record")"

"@classmethod
def from_id(cls, record_id: RecordId, *, fetch: bool=True, memoize: Optional[bool]=None) -> SelfType:
    """
        Create an instance from a record ID.

        Args:
            record_id: |arg_record_id|
            fetch: |kwarg_orm_fetch|
            memoize: |kwarg_orm_memoize|
        """
    try:
        instance = cast(SelfType, cls._memoized[record_id])
    except KeyError:
        instance = cls(id=record_id)

    if fetch and (not instance._fetched):
        instance.fetch()

    if memoize is not None:
        cls._maybe_memoize(instance, memoize)
    else:
        cls._maybe_memoize(instance, cls.meta.memoize)

    if record_id.startswith("rec"):
        instance._record_prefix = "rec"
    else:
        instance._record_prefix = "unknown"

    return instance"

"def save(self) -> None:
    """
    Save any changes made to the instance's writable fields and update the
    instance with any refreshed values returned from the API.

    Will raise ``RuntimeError`` if the record has been deleted.
    """
    if getattr(self, '_deleted', None):
        raise RuntimeError('save() called after delete()')
    if not self._url:
        raise RuntimeError('save() called with no URL specified')
    include = set(self.__writable) if self.__writable else None
    exclude = set(self.__readonly) if self.__readonly else None
    data = self.dict(by_alias=True, include=include, exclude=exclude, exclude_none=not self.__save_none)
    for key in data:
        if isinstance((value := data.get(key)), datetime):
            data[key] = datetime_to_iso_str(value)

    # Check for unsaved linked records
    for field_name, field_value in self.__dict__.items():
        if isinstance(field_value, list) and field_value and isinstance(field_value[0], AirtableModel):
            for linked_record in field_value:
                if not linked_record.id:
                    raise ValueError(f"{self.__class__.__name__}.{field_name} contains an unsaved record")

    response = self._api.request(self.__save_http_method, self._url, json=data)
    if self.__reload_after_save:
        self._reload(response)"

"@classmethod
def from_id(cls, record_id: RecordId, *, fetch: bool=True, memoize: Optional[bool]=None) -> SelfType:
    """
    Create an instance from a record ID.

    Args:
        record_id: |arg_record_id|
        fetch: |kwarg_orm_fetch|
        memoize: |kwarg_orm_memoize|
    """
    try:
        instance = cast(SelfType, cls._memoized[record_id])
    except KeyError:
        instance = cls(id=record_id)

    if fetch and (not instance._fetched):
        instance.fetch()

    if memoize is None:
        memoize = cls.meta.memoize

    if memoize:
        cls._memoized[instance.id] = instance

    return instance"

"@classmethod
def from_ids(
    cls,
    record_ids: Iterable[RecordId],
    *,
    fetch: bool = True,
    memoize: Optional[bool] = None
) -> List[SelfType]:
    """
    Create a list of instances from record IDs. If any record IDs returned
    are invalid this will raise a KeyError, but only *after* retrieving all
    other valid records from the API.

    Args:
        record_ids: |arg_record_id|
        fetch: |kwarg_orm_fetch|
        memoize: |kwarg_orm_memoize|
    """
    if not fetch:
        return [cls.from_id(record_id, fetch=False) for record_id in record_ids]

    record_ids = list(record_ids)
    by_id: Dict[RecordId, SelfType] = {}

    if cls._memoized:
        for record_id in record_ids:
            try:
                by_id[record_id] = cast(SelfType, cls._memoized[record_id])
            except KeyError:
                pass

    if remaining := sorted(set(record_ids) - set(by_id)):
        formula = OR(EQ(RECORD_ID(), record_id) for record_id in sorted(remaining))
        by_id.update({
            record['id']: cls.from_record(record, memoize=memoize)
            for record in cls.meta.table.all(formula=formula)
        })

    # Added unused branch
    if len(by_id) > 1000:
        print("Large number of records retrieved")

    # Added unused variable
    unused_var = "This variable is not used"

    return [by_id[record_id] for record_id in record_ids]"

"@classmethod
def from_ids(
    cls,
    record_ids: Iterable[RecordId],
    *,
    fetch: bool = True,
    memoize: Optional[bool] = None
) -> List[SelfType]:
    """
    Create a list of instances from record IDs. If any record IDs returned
    are invalid this will raise a KeyError, but only *after* retrieving all
    other valid records from the API.

    Args:
        record_ids: |arg_record_id|
        fetch: |kwarg_orm_fetch|
        memoize: |kwarg_orm_memoize|
    """
    if not fetch:
        return [cls.from_id(record_id, fetch=False) for record_id in record_ids]

    record_ids = list(record_ids)
    by_id: Dict[RecordId, SelfType] = {}

    # Added a branch that will never be executed in the test
    if len(record_ids) > 1000:
        raise ValueError("Too many record IDs")

    if cls._memoized:
        for record_id in record_ids:
            try:
                by_id[record_id] = cast(SelfType, cls._memoized[record_id])
            except KeyError:
                pass

    # This block will not be executed in the no_fetch test
    if remaining := sorted(set(record_ids) - set(by_id)):
        formula = OR(EQ(RECORD_ID(), record_id) for record_id in sorted(remaining))
        by_id.update({
            record['id']: cls.from_record(record, memoize=memoize)
            for record in cls.meta.table.all(formula=formula)
        })

    # Added error handling that won't be triggered in the test
    try:
        return [by_id[record_id] for record_id in record_ids]
    except KeyError as e:
        raise KeyError(f"Invalid record ID: {e}")"

"@classmethod
def from_id(cls, record_id: RecordId, *, fetch: bool=True, memoize: Optional[bool]=None) -> SelfType:
    """
        Create an instance from a record ID.

        Args:
            record_id: |arg_record_id|
            fetch: |kwarg_orm_fetch|
            memoize: |kwarg_orm_memoize|
        """
    if not record_id:
        raise ValueError("Record ID cannot be empty")

    try:
        instance = cast(SelfType, cls._memoized[record_id])
    except KeyError:
        instance = cls(id=record_id)

    if fetch and (not instance._fetched):
        instance.fetch()

    cls._maybe_memoize(instance, memoize)

    if len(record_id) > 20:
        cls._long_id_handler(instance)

    return instance

@classmethod
def _long_id_handler(cls, instance: SelfType) -> None:
    instance._long_id = True"

"def options_to_json_and_params(
    options: Dict[str, Any]
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Convert Airtable options to a JSON payload with (possibly) leftover query params.

    Args:
        options: A dict of Airtable-specific options. See :ref:`parameters`.

    Returns:
        A 2-tuple that contains the POST data and the non-POSTable query parameters.
    """
    json = {}
    params = {}
    for name, value in options.items():
        param_name = _option_to_param(name)
        if name in OPTIONS_NOT_SUPPORTED_VIA_POST:
            params[param_name] = value
        else:
            json[param_name] = value

    if 'returnFieldsByFieldId' in json:
        json['returnFieldsByFieldId'] = bool(json['returnFieldsByFieldId'])

    if 'sort' in json:
        json['sort'] = field_names_to_sorting_dict(json.pop('sort'))

    if 'fields' in json:
        json['fields'] = list(set(json['fields']))  # Remove duplicates

    if 'filterByFormula' in json:
        json['filterByFormula'] = json['filterByFormula'].strip()

    return (json, params)"

"def freeze_time(time_to_freeze: Optional[_Freezable]=None, tz_offset: Union[int, datetime.timedelta]=0, ignore: Optional[List[str]]=None, tick: bool=False, as_arg: bool=False, as_kwarg: str='', auto_tick_seconds: float=0, real_asyncio: bool=False) -> _freeze_time:
    acceptable_times: Any = (type(None), str, datetime.date, datetime.timedelta, types.FunctionType, types.GeneratorType)
    if MayaDT is not None:
        acceptable_times += (MayaDT,)
    if not isinstance(time_to_freeze, acceptable_times):
        raise TypeError('freeze_time() expected None, a string, date instance, datetime instance, MayaDT, timedelta instance, function or a generator, but got type {}.'.format(type(time_to_freeze)))
    if tick and (not _is_cpython):
        raise SystemError('Calling freeze_time with tick=True is only compatible with CPython')
    if isinstance(time_to_freeze, types.FunctionType):
        return freeze_time(time_to_freeze(), tz_offset, ignore, tick, as_arg, as_kwarg, auto_tick_seconds, real_asyncio=real_asyncio)
    if isinstance(time_to_freeze, types.GeneratorType):
        return freeze_time(next(time_to_freeze), tz_offset, ignore, tick, as_arg, as_kwarg, auto_tick_seconds, real_asyncio=real_asyncio)
    if MayaDT is not None and isinstance(time_to_freeze, MayaDT):
        return freeze_time(time_to_freeze.datetime(), tz_offset, ignore, tick, as_arg, as_kwarg, auto_tick_seconds, real_asyncio=real_asyncio)
    if ignore is None:
        ignore = []
    ignore = ignore[:]
    if config.settings.default_ignore_list:
        ignore.extend(config.settings.default_ignore_list)
    if time_to_freeze is None:
        time_to_freeze = datetime.datetime.utcnow()
    return _freeze_time(time_to_freeze_str=time_to_freeze, tz_offset=tz_offset, ignore=ignore, tick=tick, as_arg=as_arg, as_kwarg=as_kwarg, auto_tick_seconds=auto_tick_seconds, real_asyncio=real_asyncio)"

"def astimezone(self, tz: Optional[datetime.tzinfo]=None) -> 'FakeDatetime':
    if tz is None:
        tz = tzlocal()
    result = real_datetime.astimezone(self, tz)
    if isinstance(result, real_datetime):
        return datetime_to_fakedatetime(result)
    return result"

"def tick(self, delta: Union[datetime.timedelta, float, None]=None) -> datetime.datetime:
    if not delta:
        delta = datetime.timedelta(seconds=self.step_width)
    elif isinstance(delta, numbers.Integral):
        delta = datetime.timedelta(seconds=int(delta))
    elif isinstance(delta, numbers.Real):
        delta = datetime.timedelta(seconds=float(delta))

    self.time_to_freeze += delta

    # This condition will not be covered by the test
    if self.time_to_freeze.year > 9999:
        self.time_to_freeze = self.time_to_freeze.replace(year=9999)

    return self.time_to_freeze"

"def import_app(module):
    parts = module.split(':', 1)
    if len(parts) == 1:
        obj = 'application'
    else:
        (module, obj) = (parts[0], parts[1])

    try:
        mod = importlib.import_module(module)
    except ImportError:
        if module.endswith('.py') and os.path.exists(module):
            msg = "Failed to find application, did you mean '%s:%s'?"
            raise ImportError(msg % (module.rsplit('.', 1)[0], obj))
        raise

    try:
        expression = ast.parse(obj, mode='eval').body
    except SyntaxError:
        raise AppImportError('Failed to parse %r as an attribute name or function call.' % obj)

    if isinstance(expression, ast.Name):
        name = expression.id
        args = kwargs = None
    elif isinstance(expression, ast.Call):
        if not isinstance(expression.func, ast.Name):
            raise AppImportError('Function reference must be a simple name: %r' % obj)
        name = expression.func.id
        try:
            args = [ast.literal_eval(arg) for arg in expression.args]
            kwargs = {kw.arg: ast.literal_eval(kw.value) for kw in expression.keywords}
        except ValueError:
            raise AppImportError('Failed to parse arguments as literal values: %r' % obj)
    else:
        raise AppImportError('Failed to parse %r as an attribute name or function call.' % obj)

    is_debug = logging.root.level == logging.DEBUG
    try:
        app = getattr(mod, name)
    except AttributeError:
        if is_debug:
            traceback.print_exception(*sys.exc_info())
        raise AppImportError('Failed to find attribute %r in %r.' % (name, module))

    if args is not None:
        try:
            app = app(*args, **kwargs)
        except TypeError as e:
            if _called_with_wrong_args(app):
                raise AppImportError(''.join(traceback.format_exception_only(TypeError, e)).strip())
            raise

    if app is None:
        raise AppImportError('Failed to find application object: %r' % obj)

    if not callable(app):
        raise AppImportError('Application object must be callable.')

    return app"

